require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/bank.php';require_role(['officer','admin']);if($_SERVER['REQUEST_METHOD']!=='POST')redirect('fines.php');verify_csrf();$id=(int)($_POST['fine_id']??0);$s=$pdo->prepare('SELECT id,status,bank_status FROM fines WHERE id=?');$s->execute([$id]);$f=$s->fetch();if(!$f){set_flash('danger','Штраф не найден.');redirect('fines.php');}if($f['status']!=='issued'||$f['bank_status']==='sent'){set_flash('warning','Повторная отправка для этого штрафа не требуется.');redirect('fines.php');}$result=dispatch_fine_to_bank($pdo,$config,$id);set_flash($result['ok']?'success':'danger',$result['ok']?'Начисление передано в банк.':('Банк не подтвердил отправку: '.$result['message']));redirect('fines.php');
